"""Minimal obs-websocket v5 client (only what OWCSKR needs). Uses the `websockets` package."""
import asyncio, base64, hashlib, json, os, sys, uuid
import websockets
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from platform_util import obs_config_dir

CONFIG = os.path.join(obs_config_dir(), 'plugin_config', 'obs-websocket', 'config.json')


def local_password():
    """The OBS websocket password lives only in OBS's own local config (generated by tools/obs_setup.py)."""
    with open(CONFIG, encoding='utf-8') as f:
        return json.load(f).get('server_password', '')


class OBS:
    def __init__(self, host='127.0.0.1', port=4455, password=None):
        self.url = f'ws://{host}:{port}'
        self.password = password if password is not None else local_password()
        self.ws = None

    async def connect(self):
        self.ws = await websockets.connect(self.url, max_size=64 * 1024 * 1024)
        hello = json.loads(await self.ws.recv())['d']
        ident = {'rpcVersion': 1, 'eventSubscriptions': 0}
        auth = hello.get('authentication')
        if auth:
            secret = base64.b64encode(hashlib.sha256((self.password + auth['salt']).encode()).digest()).decode()
            ident['authentication'] = base64.b64encode(hashlib.sha256((secret + auth['challenge']).encode()).digest()).decode()
        await self.ws.send(json.dumps({'op': 1, 'd': ident}))
        msg = json.loads(await self.ws.recv())
        if msg.get('op') != 2:
            raise RuntimeError(f'OBS identify failed: {msg}')
        return self

    async def call(self, request_type, data=None):
        rid = uuid.uuid4().hex
        await self.ws.send(json.dumps({'op': 6, 'd': {'requestType': request_type, 'requestId': rid, 'requestData': data or {}}}))
        while True:
            msg = json.loads(await asyncio.wait_for(self.ws.recv(), timeout=30))
            if msg.get('op') == 7 and msg['d'].get('requestId') == rid:
                st = msg['d']['requestStatus']
                if not st.get('result'):
                    raise RuntimeError(f"{request_type} failed: {st.get('code')} {st.get('comment')}")
                return msg['d'].get('responseData') or {}

    async def screenshot(self, source, width=1920, height=1080):
        r = await self.call('GetSourceScreenshot', {'sourceName': source, 'imageFormat': 'png', 'imageWidth': width, 'imageHeight': height})
        return base64.b64decode(r['imageData'].split(',', 1)[1])

    async def close(self):
        if self.ws:
            await self.ws.close()
